from collections import defaultdict
from fractions import Fraction
from itertools import product
from pathlib import Path
import json
from src.C_gamma import build_gamma_schema

for n in (1, 2, 3):
    schema = build_gamma_schema(n)
    gamma = defaultdict(lambda: defaultdict(Fraction))
    for row in schema['inhomogeneous_deformation']['gamma_coefficients']:
        gamma[(row['X'], row['Y'])][(row['parameter'], row['Z'])] += Fraction(row['coeff'])
    base_data = json.loads((Path('data') / schema['base_schema']).read_text())
    base = defaultdict(lambda: defaultdict(Fraction))
    for row in base_data['structure_constants']:
        base[(row['X'], row['Y'])][row['Z']] += Fraction(row['coeff'])
    parity = base_data['parity']
    gens = base_data['basis']['odd'] + base_data['basis']['even']
    fails = 0
    example = None
    for x, y, z in product(gens, repeat=3):
        jac = defaultdict(Fraction)
        for outer, middle_a, middle_b, sign in (
            (x, y, z, -1 if parity[x] * parity[z] else 1),
            (y, z, x, -1 if parity[y] * parity[x] else 1),
            (z, x, y, -1 if parity[z] * parity[y] else 1),
        ):
            for w, bcoef in base[(middle_a, middle_b)].items():
                for term, coef in gamma[(outer, w)].items():
                    jac[term] += sign * bcoef * coef
            inner_sign = -1 if parity[outer] else 1
            for (parameter, w), gcoef in gamma[(middle_a, middle_b)].items():
                for out, bcoef in base[(outer, w)].items():
                    jac[(parameter, out)] += sign * inner_sign * gcoef * bcoef
        if any(jac.values()):
            fails += 1
            if fails == 1:
                example = (x, y, z, {k:v for k,v in jac.items() if v})
    print(f'n={n}: cocycle failures={fails}', f'example={example}' if fails else '')
