import json
from pathlib import Path
from fractions import Fraction
import sympy as sp

def add_scaled(target, source, scale):
    for k,v in source.items():
        target[k] = target.get(k, Fraction(0)) + scale*v
        if not target[k]: del target[k]

def echelon(columns):
    pivots={}
    for name, vector in columns:
        residual=dict(vector)
        for pivot,(basis,_) in pivots.items():
            factor=residual.get(pivot,Fraction(0))
            if factor: add_scaled(residual,basis,-factor)
        if residual:
            pivot=min(residual)
            factor=residual[pivot]
            pivots[pivot]=({r:v/factor for r,v in residual.items()}, name)
    return pivots

def reduce(vector,pivots):
    residual=dict(vector)
    for pivot,(basis,_) in pivots.items():
        factor=residual.get(pivot,Fraction(0))
        if factor: add_scaled(residual,basis,-factor)
    return residual

for n in (1,2,3):
    p=Path('data')
    cb=json.loads((p/f'C_{n}_coboundary.json').read_text())
    ga=json.loads((p/f'C_{n}_gamma.json').read_text())['inhomogeneous_deformation']
    variables=[]
    for block in (cb['linear_map_f']['even_to_odd'],cb['linear_map_f']['odd_to_even']):
        for row in block['coefficients']:
            variables.extend(row)
    A={v:{} for v in variables}
    for rec in cb['coboundary_coefficients']:
        row=(rec['X'],rec['Y'],rec['Z'])
        for t in rec['terms']:
            A[t['parameter']][row]=Fraction(t['coeff'])
    pivots=echelon([(v,A[v]) for v in variables])
    params=[]
    for row in ga['gb_matrix']['entries']:
        params.extend(row)
    G={v:{} for v in params}
    for rec in ga['gamma_coefficients']:
        if rec['Z']=='K': continue
        row=(rec['X'],rec['Y'],rec['Z'])
        G[rec['parameter']][row]=G[rec['parameter']].get(row,Fraction(0))+Fraction(rec['coeff'])
    residues={v:reduce(G[v],pivots) for v in params}
    rkeys=sorted(set().union(*(v.keys() for v in residues.values())))
    M=sp.Matrix([[sp.Rational(residues[p].get(r,Fraction(0)).numerator,residues[p].get(r,Fraction(0)).denominator) for p in params] for r in rkeys])
    null=M.nullspace()
    print(f'n={n} rows={len(rkeys)} phi_rank={len(pivots)} residual_rank={M.rank()} gb_count={len(params)} nullity={len(null)}')
    if null:
        print(' null basis vectors:',null)
    allplus=sp.ones(len(params),1)
    print(' all_plus_trivial_mod_K=',M*allplus==sp.zeros(M.rows,1))
    # Full scalar-sensitive answer: adding the K rows makes these constraints explicit.
    Gfull={v:{} for v in params}
    for rec in ga['gamma_coefficients']:
        row=(rec['X'],rec['Y'],rec['Z'])
        Gfull[rec['parameter']][row]=Gfull[rec['parameter']].get(row,Fraction(0))+Fraction(rec['coeff'])
    rf={v:reduce(Gfull[v],pivots) for v in params}
    kfull=sorted(set().union(*(v.keys() for v in rf.values())))
    MF=sp.Matrix([[sp.Rational(rf[p].get(r,Fraction(0)).numerator,rf[p].get(r,Fraction(0)).denominator) for p in params] for r in kfull])
    print(' all_plus_trivial_including_K=',MF*allplus==sp.zeros(MF.rows,1),'full residual rank=',MF.rank())
