import json
from pathlib import Path
from fractions import Fraction

def add_scaled(dst, src, scale):
    for k,v in src.items():
        dst[k]=dst.get(k,Fraction(0))+scale*v
        if not dst[k]: del dst[k]
def echelon(cols):
    piv={}
    for name,vec in cols:
        r=dict(vec); c={name:Fraction(1)}
        for p,(b,bc) in piv.items():
            q=r.get(p,Fraction(0))
            if q: add_scaled(r,b,-q); add_scaled(c,bc,-q)
        if r:
            p=min(r);q=r[p]
            piv[p]=({k:v/q for k,v in r.items()},{k:v/q for k,v in c.items()})
    return piv
def reduce(vec,piv):
    r=dict(vec);c={}
    for p,(b,bc) in piv.items():
        q=r.get(p,Fraction(0))
        if q: add_scaled(r,b,-q);add_scaled(c,bc,q)
    return r,c
for n in (1,2,3):
    d=Path('data')
    cb=json.loads((d/f'C_{n}_coboundary.json').read_text())
    ga=json.loads((d/f'C_{n}_gamma.json').read_text())['inhomogeneous_deformation']
    vars=[v for blk in (cb['linear_map_f']['even_to_odd'],cb['linear_map_f']['odd_to_even']) for row in blk['coefficients'] for v in row]
    A={v:{} for v in vars}
    for r in cb['coboundary_coefficients']:
        key=(r['X'],r['Y'],r['Z'])
        for t in r['terms']: A[t['parameter']][key]=Fraction(t['coeff'])
    pA=echelon([(v,A[v]) for v in vars])
    gb=[x for row in ga['gb_matrix']['entries'] for x in row]
    G={v:{} for v in gb}; K={v:{} for v in gb}
    for r in ga['gamma_coefficients']:
        key=(r['X'],r['Y'],r['Z']);c=Fraction(r['coeff'])
        (K if r['Z']=='K' else G)[r['parameter']][key]= (K if r['Z']=='K' else G)[r['parameter']].get(key,Fraction(0))+c
    rankAG=len(echelon([(v,A[v]) for v in vars]+[(v,G[v]) for v in gb]))
    allplus={}
    for v in gb: add_scaled(allplus,G[v],Fraction(1))
    residual,solution=reduce(allplus,pA)
    pk=echelon([(v,K[v]) for v in gb])
    print(f'n={n}: rank(delta)={len(pA)}, rank(delta+all gamma columns)={rankAG}, quotient rank={rankAG-len(pA)}, allplus residual terms={len(residual)}, allplus f nonzeros={sum(bool(x) for x in solution.values())}, central-K rank={len(pk)} of {len(gb)}')
